-- Final nested catalogue projections follow the canonical group helper in81.
-- They never aggregate NULL groups from historical soft-deleted/revoked memberships.
-- Draft/cover projection access remains caller-authorized; tombstones and source
-- withdrawal are enforced inside the projection as well as endpoint predicates.

CREATE OR REPLACE FUNCTION platform.catalog_manga_base(value TEXT) RETURNS JSONB LANGUAGE SQL STABLE AS $$
 SELECT jsonb_strip_nulls((m.metadata - 'links') || jsonb_build_object('id',m.id,'created_at',platform.catalog_timestamp(m.created_at),'updated_at',platform.catalog_timestamp(m.updated_at),'published_at',platform.catalog_timestamp(m.published_at),'deleted_at',platform.catalog_timestamp(m.deleted_at),'state',m.state,'title',m.title,'year',m.year,'language',m.language,'demographic',m.demographic,'status',m.publication_status,'content_rating',m.content_rating,'locked',m.locked,'version',m.version)) FROM platform.catalog_manga m WHERE m.id=value AND m.deleted_at IS NULL AND m.protocol_source_visible AND platform.protocol_source_is_visible(m.protocol_series_id)
$$;

CREATE OR REPLACE FUNCTION platform.catalog_cover_json(value TEXT) RETURNS JSONB LANGUAGE SQL STABLE AS $$
 SELECT jsonb_strip_nulls(jsonb_build_object('id',c.id,'created_at',platform.catalog_timestamp(c.created_at),'updated_at',platform.catalog_timestamp(c.updated_at),'ext',c.ext,'dimensions',c.dimensions,'volume',c.volume,'language',c.language,'description',c.description,'version',c.version,'relationships',jsonb_build_object('uploader',jsonb_build_object('id',c.uploader_id,'name',c.uploader_name,'version',1)))) FROM platform.catalog_covers c WHERE c.id=value AND platform.protocol_source_is_visible(c.protocol_event_id) AND EXISTS(SELECT 1 FROM platform.catalog_manga parent WHERE parent.id=c.manga_id AND parent.deleted_at IS NULL AND parent.protocol_source_visible AND platform.protocol_source_is_visible(parent.protocol_series_id)) AND c.deleted_at IS NULL AND platform.protocol_source_is_visible(c.protocol_event_id)
$$;

CREATE OR REPLACE FUNCTION platform.catalog_relations_json(value TEXT) RETURNS JSONB LANGUAGE SQL STABLE AS $$
 SELECT COALESCE(jsonb_agg(platform.catalog_manga_base(m.id) || jsonb_build_object('type',r.relation_type,'relationships',jsonb_strip_nulls(jsonb_build_object('tags',platform.catalog_manga_tags_json(m.id),'cover',(SELECT platform.catalog_cover_json(c.id) FROM platform.catalog_covers c WHERE c.manga_id=m.id AND c.deleted_at IS NULL AND platform.protocol_source_is_visible(c.protocol_event_id) ORDER BY c.is_main DESC,c.created_at DESC,c.id LIMIT 1)))) ORDER BY r.relation_type,m.title,m.id),'[]'::jsonb) FROM platform.catalog_relations r JOIN platform.catalog_manga m ON m.id=r.related_id WHERE r.manga_id=value AND EXISTS(SELECT 1 FROM platform.catalog_manga root WHERE root.id=value AND root.deleted_at IS NULL AND root.protocol_source_visible AND platform.protocol_source_is_visible(root.protocol_series_id)) AND m.state='published' AND m.deleted_at IS NULL AND m.protocol_source_visible AND platform.protocol_source_is_visible(m.protocol_series_id)
$$;

CREATE OR REPLACE FUNCTION platform.catalog_manga_json(value TEXT) RETURNS JSONB LANGUAGE SQL STABLE AS $$
 SELECT platform.catalog_manga_base(m.id) || jsonb_build_object('relationships',jsonb_strip_nulls(jsonb_build_object(
 'submitter',jsonb_build_object('id',m.owner_id,'name',m.owner_name,'version',1),
 'cover',(SELECT platform.catalog_cover_json(c.id) FROM platform.catalog_covers c WHERE c.manga_id=m.id AND c.deleted_at IS NULL AND platform.protocol_source_is_visible(c.protocol_event_id) ORDER BY c.is_main DESC,c.created_at DESC,c.id LIMIT 1),
 'tags',platform.catalog_manga_tags_json(m.id),
 'authors',COALESCE((SELECT jsonb_agg(platform.catalog_author_json(a.id) ORDER BY a.name,a.id) FROM platform.catalog_manga_creators mc JOIN platform.catalog_authors a ON a.id=mc.author_id WHERE mc.manga_id=m.id AND mc.role='author' AND a.deleted_at IS NULL AND platform.protocol_source_is_visible(a.protocol_event_id)),'[]'::jsonb),
 'artists',COALESCE((SELECT jsonb_agg(platform.catalog_author_json(a.id) ORDER BY a.name,a.id) FROM platform.catalog_manga_creators mc JOIN platform.catalog_authors a ON a.id=mc.author_id WHERE mc.manga_id=m.id AND mc.role='artist' AND a.deleted_at IS NULL AND platform.protocol_source_is_visible(a.protocol_event_id)),'[]'::jsonb),
 'links',m.metadata->'links','relations',platform.catalog_relations_json(m.id),'thread',platform.catalog_thread_json('manga',m.id),
 'available_languages',COALESCE((SELECT jsonb_agg(x.language ORDER BY x.language) FROM (SELECT DISTINCT c.language FROM platform.catalog_chapters c WHERE c.manga_id=m.id AND c.deleted_at IS NULL AND platform.protocol_source_is_visible(c.protocol_event_id) AND NOT c.is_unavailable)x),'[]'::jsonb),
 'available_groups',COALESCE((SELECT jsonb_agg(platform.catalog_group_json(x.group_id) ORDER BY x.group_id) FROM (SELECT DISTINCT cg.group_id FROM platform.catalog_chapter_groups cg JOIN platform.catalog_chapters c ON c.id=cg.chapter_id JOIN platform.catalog_groups g ON g.id=cg.group_id WHERE c.manga_id=m.id AND c.deleted_at IS NULL AND NOT c.is_unavailable AND platform.protocol_source_is_visible(c.protocol_event_id) AND g.deleted_at IS NULL AND platform.protocol_group_is_visible(g.id))x),'[]'::jsonb),
 'stats',jsonb_build_object('chapters',(SELECT count(*) FROM platform.catalog_chapters c WHERE c.manga_id=m.id AND c.deleted_at IS NULL AND platform.protocol_source_is_visible(c.protocol_event_id)),'views',COALESCE(s.views,0),'follows',COALESCE(s.follows,0))))) FROM platform.catalog_manga m LEFT JOIN platform.catalog_manga_counters s ON s.manga_id=m.id WHERE m.id=value AND m.deleted_at IS NULL AND m.protocol_source_visible AND platform.protocol_source_is_visible(m.protocol_series_id)
$$;

CREATE OR REPLACE FUNCTION platform.catalog_chapter_json(value TEXT) RETURNS JSONB LANGUAGE SQL STABLE AS $$
 SELECT jsonb_strip_nulls(c.metadata || jsonb_build_object('id',c.id,'source_id',c.source_id,'created_at',platform.catalog_timestamp(c.created_at),'updated_at',platform.catalog_timestamp(c.updated_at),'published_at',platform.catalog_timestamp(c.published_at),'deleted_at',platform.catalog_timestamp(c.deleted_at),'title',c.title,'volume',c.volume,'chapter',c.chapter,'language',c.language,'is_unavailable',c.is_unavailable,'version',c.version,'relationships',jsonb_build_object('uploader',jsonb_build_object('id',c.uploader_id,'name',c.uploader_name,'version',1),'manga',platform.catalog_manga_json(c.manga_id),'groups',COALESCE((SELECT jsonb_agg(platform.catalog_group_json(cg.group_id) ORDER BY cg.group_id) FROM platform.catalog_chapter_groups cg JOIN platform.catalog_groups g ON g.id=cg.group_id WHERE cg.chapter_id=c.id AND g.deleted_at IS NULL AND platform.protocol_group_is_visible(g.id)),'[]'::jsonb),'thread',platform.catalog_thread_json('chapter',c.id),'stats',jsonb_build_object('views',COALESCE(s.views,0))))) FROM platform.catalog_chapters c LEFT JOIN platform.catalog_chapter_counters s ON s.chapter_id=c.id WHERE c.id=value AND c.deleted_at IS NULL AND platform.protocol_source_is_visible(c.protocol_event_id) AND EXISTS(SELECT 1 FROM platform.catalog_manga parent WHERE parent.id=c.manga_id AND parent.deleted_at IS NULL AND parent.state='published' AND parent.protocol_source_visible AND platform.protocol_source_is_visible(parent.protocol_series_id))
$$;
